  KEY `idx_nap_don_tt` (`trang_thai`),
  KEY `idx_nap_don_user` (`user_id`,`tao_luc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
